package UI

import (
	"fmt"
	webview "github.com/webview/webview_go"
	"net/http"
	"os"
	"slices"
	"strconv"
)

var Main = "<!DOCTYPE html>\n<html lang=\"en\">\n\n<head>\n    <meta charset=\"UTF-8\" />\n    <title>Fern Panel</title>\n    <link href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0-beta3/css/all.min.css\" rel=\"stylesheet\" />\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;600&display=swap\" />\n    <style>\n        body {\n            font-family: 'Poppins', sans-serif;\n            background-color: #121212;\n            color: #ffffff;\n            transition: background-color 0.3s, color 0.3s;\n        }\n\n        ::selection {\n            background-color: white;\n            color: #7751a2;\n        }\n\n        .preview-box {\n            background-color: #262626;\n            padding: 15px;\n            max-width: 100%;\n            border-radius: 10px;\n            box-shadow: 0 4px 10px rgba(0, 0, 0, 0.6);\n            word-wrap: break-word;\n            overflow-wrap: break-word;\n            overflow-y: auto;\n        }\n\n        .text {\n            height: 90%;\n            width: 100%;\n            text-align: center;\n            margin-top: 0.25rem;\n            color: #c2c1c1;\n            overflow-y: auto;\n            font-size: 12px;\n            white-space: pre-wrap;\n            word-wrap: break-word;\n            overflow-wrap: break-word;\n        }\n        ::-webkit-scrollbar {\n            background: none;\n        }\n        .text::-webkit-scrollbar {\n            background: none;\n        }\n        .Logs-Box {\n            height: 40vh;\n            background-color: #262626;\n            padding: 15px;\n            max-width: 100%;\n            border-radius: 10px;\n            box-shadow: 0 4px 10px rgba(0, 0, 0, 0.6);\n            word-wrap: break-word;\n            overflow-wrap: break-word;\n            overflow-y: hidden;\n        }\n\n        .Logs-Box::-webkit-scrollbar {\n            display: none;\n        }\n\n        .Logs-Box {\n            scrollbar-width: none;\n        }\n\n\n\n        input[type=\"checkbox\"] {\n            display: none;\n        }\n\n        .toggle-wrapper {\n            margin-bottom: -0.28rem;\n            display: inline-block;\n            width: 50px;\n            height: 20px;\n            background-color: #444;\n            border-radius: 50px;\n            position: relative;\n            cursor: pointer;\n        }\n\n        .toggle-wrapper::before {\n            content: \"\";\n            position: absolute;\n            top: 5px;\n            left: 5px;\n            width: 10px;\n            height: 10px;\n            background-color: #c0c0c0;\n            border-radius: 50%;\n            transition: all 0.3s ease;\n        }\n\n        input[type=\"checkbox\"]:checked + .toggle-wrapper::before {\n            transform: translateX(30px);\n            background-color: #c0c0c0;\n        }\n\n        .toggle-wrapper {\n            background-color: #444;\n        }\n\n        input[type=\"checkbox\"]:checked + .toggle-wrapper {\n            background-color: #6b6b6b;\n        }\n    </style>\n</head>\n\n<body>\n<div>\n    <div class=\"flex flex-1\">\n        <aside class=\"w-1/4 bg-[#1a1a1a] p-5 flex flex-col\" style=\"height: 100vh; overflow-y: scroll; padding-right: 0;\">\n            <h3 class=\"text-[#7751a2] p-2 text-xl mb-6 font-bold text-center bg-[#262626] rounded-lg\"\n                style=\"box-shadow: 0 4px 10px rgba(0, 0, 0, 0.6);\">\n                Fern\n            </h3>\n\n            <div class=\"preview-box mt-2\" style=\"overflow: visible;\">\n                <h4 class=\"flex justify-between items-center\">\n                        <a href=\"https://github.com/KyarottoOwO\" target=\"_blank\">\n                            <i class=\"fab fa-github text-[#7751a2]\"\n                               style=\"text-shadow: 0 5px 10px rgba(0, 0, 0, 0.6); width: 52px;\"></i>\n                        </a>\n                    <span class=\"text-[#7751a2] font-bold text-center\"\n                          style=\"text-shadow: 0 5px 10px rgba(0, 0, 0, 0.6);\">Preview</span>\n                    <span class=\"text-[#7751a2] text-sm\" id=\"DisplayC\" style=\"width: 52px; text-shadow: 0 5px 10px rgba(0, 0, 0, 0.6);\"></span>\n                </h4>\n                <div class=\"separator my-2 border-t border-[#444]\"></div>\n                <div class=\"text\" id=\"PreViewText\" style=\"height: 100%;\">\n                </div>\n            </div>\n\n            <div id=\"menuContainer\" class=\"mt-[2rem]\" style=\"overflow-y: visible\"></div>\n        </aside>\n\n        <main class=\"flex-1 p-5\" id=\"mainContent\">\n            <div class=\"bg-[#1e1e1e] p-4 rounded-lg shadow-md\">\n                Welcome to the Fern Panel! Select a menu item to get started.\n            </div>\n        </main>\n    </div>\n\n    <footer class=\"bg-[#1e1e1e] text-center p-2 text-sm\" style=\"bottom: 0; position: fixed; width: 100vw;\">\n        © 2024 Fern ｢フェルン｣ | All rights reserved\n    </footer>\n</div>\n\n<script>\n    const menuItems = [\n        {\n            \"Dashboard\": [\n                {\n                    text: 'Dashboard Home',\n                    href: '#',\n                    active: true,\n                    content: `\n                        <h2 class=\"text-2xl font-semibold mb-4\">Dashboard Home</h2>\n                        <p>Welcome to the Dashboard! Here you can see an overview of your system.</p>\n                        <div class=\"mt-4\">\n                            <i class=\"fas fa-tachometer-alt fa-3x text-[#7751a2]\"></i>\n                        </div>\n                        `\n                },\n                {\n                    text: 'Logs',\n                    href: '#',\n                    active: false,\n                    content: `<div class=\"grid-container\" style=\"display: grid; grid-template-columns: repeat(2, 1fr); grid-template-rows: repeat(4, auto); gap: 16px; padding: 0; justify-self: center; width: 100%; height: 100%;\">\n    <div class=\"Logs-Box\">\n        <h4 class=\"flex justify-between items-center\">\n            <div class=\"flex items-center\"></div>\n            <a class=\"text-[#7751a2] font-bold text-center\"\n                style=\"text-shadow: 0 5px 10px rgba(0, 0, 0, 0.6);\">Join Logs</a>\n            <span class=\"text-[#7751a2] text-sm\"\n                style=\"text-shadow: 0 5px 10px rgba(0, 0, 0, 0.6);\"></span>\n        </h4>\n        <div class=\"separator my-2 border-t border-[#444]\"></div>\n        <div class=\"text\" id=\"JoinLogsText\">Loading join logs...</div>\n    </div>\n\n    <div class=\"Logs-Box\">\n        <h4 class=\"flex justify-between items-center\">\n            <div class=\"flex items-center\"></div>\n            <span class=\"text-[#7751a2] font-bold text-center\"\n                style=\"text-shadow: 0 5px 10px rgba(0, 0, 0, 0.6);\">Leave Logs</span>\n            <span class=\"text-[#7751a2] text-sm\"\n                style=\"text-shadow: 0 5px 10px rgba(0, 0, 0, 0.6);\"></span>\n        </h4>\n        <div class=\"separator my-2 border-t border-[#444]\"></div>\n        <div class=\"text\" id=\"LeaveLogsText\">Loading leave logs...</div>\n    </div>\n\n    <div class=\"Logs-Box\">\n        <h4 class=\"flex justify-between items-center\">\n            <div class=\"flex items-center\"></div>\n            <span class=\"text-[#7751a2] font-bold text-center\"\n                style=\"text-shadow: 0 5px 10px rgba(0, 0, 0, 0.6);\">Chat Logs</span>\n            <span class=\"text-[#7751a2] text-sm\"\n                style=\"text-shadow: 0 5px 10px rgba(0, 0, 0, 0.6);\"></span>\n        </h4>\n        <div class=\"separator my-2 border-t border-[#444]\"></div>\n        <div class=\"text\" id=\"ChatLogsText\">Loading chat logs...</div>\n    </div>\n\n    <div class=\"Logs-Box\">\n        <h4 class=\"flex justify-between items-center\">\n            <div class=\"flex items-center\"></div>\n            <span class=\"text-[#7751a2] font-bold text-center\"\n                style=\"text-shadow: 0 5px 10px rgba(0, 0, 0, 0.6);\">Error Logs</span>\n            <span class=\"text-[#7751a2] text-sm\"\n                style=\"text-shadow: 0 5px 10px rgba(0, 0, 0, 0.6);\"></span>\n        </h4>\n        <div class=\"separator my-2 border-t border-[#444]\"></div>\n        <div class=\"text\" id=\"ErrorLogsText\">Loading error logs...</div>\n    </div>\n</div>\n`\n                }\n            ]\n        },\n        {\n            \"Settings\": [\n                {\n                    text: 'Toggles Options',\n                    href: '#',\n                    active: false,\n                    content: `\n                        <h2 class=\"text-2xl font-semibold mb-4\">Toggles Options</h2>\n                        <p>Manage your toggle settings here.</p>\n                        <label>\n                            <span class=\"mb-8 text-[#ddd]\">AFK now</span>\n                            <input type=\"checkbox\" id=\"afk-toggle\">\n                            <div class=\"toggle-wrapper\"></div>\n                        </label>\n                    `\n                },\n                {\n                    text: 'Text Options',\n                    href: '#',\n                    active: false,\n                    content: `\n                        <h2 class=\"text-2xl font-semibold mb-4\">Text Options</h2>\n                        <p>Customize your text settings.</p>\n                        <div class=\"mt-4\">\n                            <input type=\"text\" class=\"px-3 py-2 rounded bg-[#2a2a2a] text-white\" placeholder=\"Enter text here\"/>\n                        </div>\n                    `\n                }\n            ]\n        }\n    ];\n\n    const menuContainer = document.getElementById('menuContainer');\n    const mainContent = document.getElementById('mainContent');\n\n    function renderMenu() {\n        menuContainer.innerHTML = \"\";\n\n        menuItems.forEach(sectionObj => {\n            const sectionName = Object.keys(sectionObj)[0];\n            const itemsArray = sectionObj[sectionName];\n\n            const sectionDiv = document.createElement('div');\n            sectionDiv.classList.add(\"mb-4\");\n\n            const sectionTitle = document.createElement('h4');\n            sectionTitle.textContent = sectionName;\n            sectionTitle.classList.add(\"text-[#7751a2]\", \"mb-2\", \"text-md\", \"font-semibold\");\n            sectionDiv.appendChild(sectionTitle);\n\n            itemsArray.forEach(item => {\n                const button = document.createElement('button');\n                button.classList.add(\n                    'w-full',\n                    'text-left',\n                    'cursor-pointer',\n                    'rounded-lg',\n                    'p-3',\n                    'mb-2',\n                    'transition-colors',\n                    'duration-300',\n                    'focus:outline-none',\n                    'shadow-xl'\n                );\n\n                if (item.active) {\n                    button.classList.add('bg-[#7751a2]');\n                } else {\n                    button.classList.add('bg-[#262626]', 'hover:bg-[#624486]');\n                }\n\n                button.textContent = item.text;\n\n                button.addEventListener('click', () => {\n                    menuItems.forEach(secObj => {\n                        const secKey = Object.keys(secObj)[0];\n                        secObj[secKey].forEach(i => i.active = false);\n                    });\n\n                    item.active = true;\n                    renderMenu();\n                    mainContent.innerHTML = item.content;\n\n                    const GetJoinLogs = document.getElementById(\"JoinLogsText\");\n                    if (GetJoinLogs) {\n                        startGetJoinLogs(GetJoinLogs);\n                    }\n\n                    const GetLeaveLogs = document.getElementById(\"LeaveLogsText\");\n                    if (GetLeaveLogs) {\n                        startGetLeaveLogs(GetLeaveLogs);\n                    }\n                });\n\n                sectionDiv.appendChild(button);\n            });\n\n            menuContainer.appendChild(sectionDiv);\n        });\n    }\n\n    const PreView = document.getElementById('PreViewText');\n    const DisplayCLimit = document.getElementById(\"DisplayC\");\n\n    function startGetJoinLogs(GetJoinLogs) {\n        const ws = new WebSocket(\"/ws/logs/join\")\n        ws.onmessage = (event) => {\n            const message = JSON.parse(event.data);\n            if (message.length > 0 && GetJoinLogs.innerHTML.includes(\"Loading join logs...\")) {\n                GetJoinLogs.innerHTML = \"\"\n            }\n            GetJoinLogs.innerHTML = message + GetJoinLogs.innerHTML\n        }\n    }\n\n    function startPreviewUpdate() {\n        const ws = new WebSocket(\"/ws/preview\")\n        ws.onmessage = (event) => {\n            const message = JSON.parse(event.data);\n            PreView.innerHTML = message;\n            DisplayCLimit.textContent = `${message.length}/144`;\n        }\n    }\n\n    function startGetLeaveLogs(GetJoinLogs) {\n        const ws = new WebSocket(\"/ws/logs/leave\")\n        ws.onmessage = (event) => {\n            const message = JSON.parse(event.data);\n                    if (message.length > 0 && GetJoinLogs.innerHTML.includes(\"Loading leave logs...\")) {\n                GetJoinLogs.innerHTML = \"\"\n            }\n            GetJoinLogs.innerHTML = message + GetJoinLogs.innerHTML\n        }\n    }\n\n    startPreviewUpdate();\n    renderMenu();\n</script>\n\n</body>\n\n</html>\n"

func DisplayUI() {
	go func() {
		fmt.Println("Starting server on port " + strconv.Itoa(1932))
		http.HandleFunc("/", func(writer http.ResponseWriter, request *http.Request) {
			http.ServeFile(writer, request, "./UI/Home.html")
			//http.ServeContent(writer, request, "index.html", time.Now(), strings.NewReader(Main))
		})
		if err := http.ListenAndServe("127.0.0.1:"+strconv.Itoa(1932), nil); err != nil {
			fmt.Printf("Error starting server: %s", err)
			os.Exit(1)
		}
	}()

	w := webview.New(slices.Contains(os.Args, "--debug"))

	defer os.Exit(0)

	w.Dispatch(func() {
		w.Navigate("http://127.0.0.1:" + strconv.Itoa(1932) + "/VRChatBox.HTML")
	})

	//w.SetSize(1200, 800, webview.HintMin)
	w.SetTitle("Fern ｢フェルン｣")
	w.Run()

}
